{"list":[{"type":"eventStartConditional","center":{"x":60,"y":120},"triggerType":"afterRecordUpdated","isInterrupting":false,"id":"9ozig1mlsx","text":"After rating is given","conditionsAll":[{"type":"or","value":[{"comparison":"notEquals","subjectType":"value","cid":1,"fieldToCompare":"responseQuality","value":"-","type":"any"}]}],"conditionsAny":[],"conditionsFormula":null,"description":null},{"type":"task","center":{"x":300,"y":120},"text":"Create payload","isolateVariables":false,"returnVariableList":[],"description":null,"id":"aub7jtft8l","actionList":[{"formula":"$payload = object\create();

$response_quality = record\attribute('CInsight', id, 'responseQuality');
$request_id = record\attribute('CInsight', id, 'requestID');

$payload['value'] = ifThenElse($response_quality == 'Bad', 0, ifThenElse($response_quality == 'Oke', 0.5, 1));
$payload['traceId'] = string\replace($request_id, '-', '');

$payload['name'] = "user_quality_score";
$payload['dataType'] = "NUMERIC";

$motherPayload = json\encode($payload);

$baseUrl = ext\appSecret\get('LANGFUSE_HOST');
$urlScore = string\concatenate($baseUrl, '/api/public/scores');

